// Extrae el número y el texto del payload reenviado por la app (YCloud).
const body = $input.first().json.body || $input.first().json;
const msg = body.whatsappInboundMessage || body.message || {};
const from = msg.from || body.from || '';
const text = (msg.text && msg.text.body) || msg.text || body.text || '';

// Lógica simple de respuesta (personalízala o conéctala a un nodo de IA).
let reply;
const t = String(text).toLowerCase();
if (t.includes('precio') || t.includes('plan')) {
  reply = 'Nuestro plan Pro cuesta $29/mes e incluye bot ilimitado. ¿Te comparto el link de pago? 💳';
} else if (t.includes('hola') || t.includes('buenas')) {
  reply = '¡Hola! 👋 Soy tu asistente. ¿En qué puedo ayudarte hoy?';
} else {
  reply = 'Gracias por tu mensaje 🙌. Un agente te responderá en breve, o escribe "precios" para ver los planes.';
}

return [{ json: { from, text, reply } }];
